const esc = (value) => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = (app) => app.price ? `${Math.round(app.price)} €` : 'Gratuit';
const renderVideo = (app, video) => {
  if (!video || video.status !== 'public') return '';
  const playlist = VIDEO_DATA.playlists[video.locale];
  const languageLabel = video.locale === 'fr' ? 'français' : 'anglais';
  return `<style>.video-demo{margin:0 0 48px;padding:26px;background:#f3f8fb;border:1px solid #d7e5ee;border-radius:14px}.video-demo h2{margin:7px 0 9px}.video-frame{position:relative;width:100%;aspect-ratio:16/9;margin:20px 0;background:#071f39;border-radius:10px;overflow:hidden;box-shadow:0 18px 40px #071f3926}.video-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.video-links{display:flex;align-items:center;gap:18px;flex-wrap:wrap}</style><section class="video-demo" aria-labelledby="video-demo-title"><p class="eyebrow dark">Démonstration produit</p><h2 id="video-demo-title">Voir ${esc(app.name)} en action</h2><p>Une démonstration courte en ${languageLabel}, avec sous-titres YouTube disponibles.</p><div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${esc(video.youtubeId)}" title="${esc(video.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><div class="video-links"><a class="button" href="https://youtu.be/${esc(video.youtubeId)}" target="_blank" rel="noopener">Voir sur YouTube</a><a class="text-link" href="${esc(playlist.url)}" target="_blank" rel="noopener">Playlist ${esc(playlist.name)}</a></div></section>`;
};
module.exports = (req, res) => {
  const slug = Array.isArray(req.query.slug) ? req.query.slug[0] : req.query.slug;
  const app = APPS.find(item => item.slug === slug);
  if (!app) return res.status(404).setHeader('Content-Type','text/html; charset=utf-8').send('<!doctype html><html lang="fr"><title>Application introuvable | Dyonysos</title><body><h1>Application introuvable</h1><p><a href="/applications-odoo">Voir le catalogue Odoo</a></p></body></html>');
  const canonical = `https://dyonysos.fr/blog/odoo/${app.slug}`;
  const title = `${app.name} pour Odoo 19 | Dyonysos`;
  const description = `${app.summary}`.slice(0, 158);
  const featureHtml = app.features.map(item => `<li>${esc(item)}</li>`).join('');
  const peers = APPS.filter(item => item.group === app.group && item.slug !== app.slug).slice(0,3);
  const related = peers.map(item => `<a href="/blog/odoo/${esc(item.slug)}">${esc(item.name)}</a>`).join('');
  const video = VIDEO_DATA.videos[app.slug];
  const videoHtml = renderVideo(app, video);
  const schema = [{
    '@context':'https://schema.org','@type':'SoftwareApplication',name:app.name,applicationCategory:'BusinessApplication',operatingSystem:'Web',softwareVersion:app.version,description:app.summary,image:`https://dyonysos.fr${app.image}`,url:canonical,offers:{'@type':'Offer',price:app.price,priceCurrency:app.currency,url:app.appsUrl,availability:'https://schema.org/InStock'},publisher:{'@type':'Organization',name:'Dyonysos',url:'https://dyonysos.fr'}
  },{
    '@context':'https://schema.org','@type':'Article',headline:title,description,mainEntityOfPage:canonical,image:`https://dyonysos.fr${app.image}`,author:{'@type':'Organization',name:'Dyonysos'},publisher:{'@type':'Organization',name:'Dyonysos',logo:{'@type':'ImageObject',url:'https://dyonysos.fr/logo-dyonysos-wordmark.png'}},datePublished:'2026-09-07',dateModified:'2026-09-07'
  },{
    '@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Accueil',item:'https://dyonysos.fr/'},{'@type':'ListItem',position:2,name:'Applications Odoo',item:'https://dyonysos.fr/applications-odoo'},{'@type':'ListItem',position:3,name:app.name,item:canonical}]
  }];
  if (video?.status === 'public') schema.push({
    '@context':'https://schema.org','@type':'VideoObject',name:video.title,description:`Démonstration de ${app.name} pour Odoo 19`,thumbnailUrl:`https://i.ytimg.com/vi/${video.youtubeId}/hqdefault.jpg`,uploadDate:video.publishedAt,embedUrl:`https://www.youtube-nocookie.com/embed/${video.youtubeId}`,contentUrl:`https://youtu.be/${video.youtubeId}`
  });
  const body = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta property="og:type" content="article"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:image" content="https://dyonysos.fr${esc(app.image)}"><meta property="og:url" content="${canonical}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/common.css"><link rel="stylesheet" href="/theme.css"><link rel="stylesheet" href="/odoo-apps.css"><script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script></head><body><header class="odoo-header"><div class="wrap nav"><a class="brand" href="/"><img src="/logo-dyonysos-wordmark.png" alt="Dyonysos" width="168" height="48"></a><nav aria-label="Navigation principale"><a href="/">Accueil</a><a href="/solutions">Solutions</a><a href="/applications-odoo">Applications Odoo</a><a href="/blog">Blog</a></nav><a class="button compact" href="/contact?objet=${encodeURIComponent(app.name)}">Parler de cette application</a></div></header><main><article><header class="article-hero"><div class="wrap"><div><p class="eyebrow">${esc(app.groupTitle)} pour Odoo 19 Community</p><h1>${esc(app.name)}</h1><p>${esc(app.summary)}</p><div class="article-meta"><strong>${money(app)}</strong><a class="button" href="${esc(app.appsUrl)}" target="_blank" rel="noopener">Voir sur Odoo Apps</a></div></div><img src="${esc(app.image)}" alt="Capture de ${esc(app.name)} dans Odoo 19" width="960" height="600"></div></header><div class="article-body"><div class="wrap article-layout"><div class="article-content">${videoHtml}<h2>Le besoin métier traité</h2><p>${esc(app.description.split(' Cette application')[0].split(' Elle apporte')[0].slice(0,850) || app.summary)}</p><p>${esc(app.name)} s'adresse aux ${esc(app.audience.toLowerCase())}. L'objectif commercial et opérationnel reste précis : ${esc(app.angle)}.</p><h2>Fonctionnalités principales</h2><ul class="feature-list">${featureHtml}</ul><h2>Pourquoi l'ajouter à Odoo Community</h2><p>Cette application conserve le socle Odoo pour les utilisateurs, les droits d'accès et les données déjà en place. Elle ajoute un périmètre métier identifiable sans imposer le remplacement complet de votre système de gestion.</p><p>Une vérification de compatibilité reste nécessaire avant installation : version exacte d'Odoo, dépendances, modules déjà personnalisés, hébergement et données à reprendre.</p><h2>Déploiement conseillé</h2><h3>1. Cadrage court</h3><p>Nous identifions le processus prioritaire, les rôles concernés et les données nécessaires. Cette étape confirme que l'application répond au besoin réel.</p><h3>2. Installation sur une base de test</h3><p>Le module est installé sur un environnement de test avec un jeu de données représentatif. Les écrans, droits et dépendances sont contrôlés avant toute mise en production.</p><h3>3. Mise en service accompagnée</h3><p>Le passage en production comprend le paramétrage utile, la reprise limitée aux données nécessaires et une prise en main centrée sur les tâches quotidiennes.</p><div class="note"><strong>À savoir</strong><br>La licence, le prix et le périmètre affichés correspondent à la fiche Odoo Apps observée au 7 septembre 2026. Les services d'installation, de reprise et d'accompagnement font l'objet d'un devis séparé.</div><h2>Parler de votre cas</h2><p>Présentez-nous votre version d'Odoo, votre mode d'hébergement et le processus que vous voulez améliorer. Nous vous indiquerons le chemin le plus court pour tester ${esc(app.name)} proprement.</p><a class="button" href="/contact?objet=${encodeURIComponent(app.name)}">Demander un échange</a></div><aside class="sidebar"><strong>${esc(app.name)}</strong><p>${esc(app.groupTitle)}</p><p><b>Version :</b> Odoo ${esc(app.version.split('.')[0])}</p><p><b>Licence :</b> ${esc(app.license)}</p><p><b>Prix de l'application :</b> ${money(app)}</p><a href="${esc(app.appsUrl)}" target="_blank" rel="noopener">Fiche Odoo Apps</a><a href="/applications-odoo">Tout le catalogue Dyonysos</a></aside></div></div></article><section class="related"><div class="wrap"><p class="eyebrow dark">À découvrir aussi</p><h2>Autres applications ${esc(app.groupTitle.toLowerCase())}</h2><div class="related-grid">${related}</div></div></section></main><footer><div class="wrap footer-grid"><div><img src="/logo-dyonysos-wordmark.png" alt="Dyonysos" width="168" height="48"><p>Applications Odoo 19, intégration et accompagnement.</p></div><div><strong>Applications</strong><a href="/applications-odoo">Catalogue</a><a href="/blog">Blog</a></div><div><strong>Contact</strong><a href="/contact?objet=Applications%20Odoo">Étudier un besoin</a><a href="/mentions-legales">Mentions légales</a></div></div></footer></body></html>`;
  res.setHeader('Content-Type','text/html; charset=utf-8');
  res.setHeader('Cache-Control','public, s-maxage=3600, stale-while-revalidate=86400');
  return res.status(200).send(body);
};
